import unittest

class ZahlenTest(unittest.TestCase):
    def test_faelle(self):
        for n, erwartet in [(2, 4), (3, 6)]:
            with self.subTest(n=n):
                self.assertEqual(n * 2, erwartet)

r = unittest.TestResult()
ZahlenTest("test_faelle").run(r)
print(r.testsRun)
print(r.wasSuccessful())

from contextlib import contextmanager

@contextmanager
def bereit():
    print("Start")
    try:
        yield "Wert"
    finally:
        print("Ende")

with bereit() as wert:
    print(wert)
